using System;
using System.Linq;
using System.Reflection;
using System.Collections.Generic;
using NUnit.Framework;
using UnityEngine;
namespace ArenaTatica.Core.Tests
{
 public class SomnaxGuardaVozesTests
 {
  static object Call(Match m,string method,params object[] args)=>typeof(Match).GetMethod(method,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(m,args);
  static Match New(string first="somnax",string enemy="perry") {
   var m=Match.New(new MatchSetup{flatMap=true,team1=new[]{first,"ciantia","talyssa"},team2=new[]{enemy}});
   foreach(var t in m.S.tiles){t.terrain=Terrain.Livre;t.height=0;t.obj=0;t.coins=0;t.trap=0;}
   var a=m.S.fighters.First(x=>x.def==first);a.cell=new Cell(2,2);a.pa=20;a.pm=5;
   int z=4;foreach(var f in m.S.fighters.Where(x=>x!=a)) f.cell=new Cell(7,z++);
   m.S.active=m.S.timeline.IndexOf(a.id);m.S.placing=0;return m;
  }
  static Fighter A(Match m)=>m.S.Active;
  static Fighter Enemy(Match m)=>m.S.fighters.First(x=>!m.S.Ally(x.team,A(m).team));
  static SkillDef Fixed(Fighter a,string id,int damage=2) {var sk=JsonUtility.FromJson<SkillDef>(JsonUtility.ToJson(Content.Skill(a,id)));sk.damage=damage;sk.maxDamage=0;return sk;}
  static void Strike(Match m,Fighter a,Fighter b,SkillDef sk,Face defense=Face.Trava){m.Forced.Clear();m.Forced.Enqueue(Face.Trava);m.Forced.Enqueue(defense);Call(m,"Strike",a,sk,b.cell,false,null);}
  static bool Use(Match m,Fighter a,string id,Cell c,Cell c2,out List<GameEvent> e,out string why)=>m.Apply(new Command{kind="skill",fighter=a.id,revision=m.S.revision,skill=id,cell=c,cell2=c2},a.team,out e,out why);
  [TearDown] public void Reset()=>Content.ApplyEdits("");
  [Test] public void SomnaxUsesExactAuthorStatsAndRegularFootprint(){var d=Content.Default("somnax");Assert.AreEqual(11,d.hp);Assert.AreEqual(6,d.pa);Assert.AreEqual(4,d.pm);Assert.AreEqual(6,d.initiative);Assert.AreEqual(0,d.armor);Assert.IsTrue(d.legendary);Assert.AreEqual(1,Board.SizeOf(A(New())));Assert.AreEqual(5,d.level);}
  [Test] public void PactoAndRenunciaHaveUseLimitsRatherThanDamageCaps(){var a=A(New());Assert.AreEqual(2,Content.Skill(a,"pacto").perTurn);Assert.AreEqual(1,Content.Skill(a,"renuncia").perTurn);Assert.AreEqual(2,Content.Skill(a,"pacto").damage);Assert.AreEqual(0,Content.Skill(a,"pacto").maxDamage);}
  [Test] public void PactoIgnoresShieldButKeepsArmor(){var m=New();var a=A(m);var b=Enemy(m);b.cell=new Cell(3,2);b.armor=2;b.hp=20;a.twinBondUsed=true;Strike(m,a,b,Fixed(a,"pacto",3),Face.Escudo);Assert.AreEqual(19,b.hp);}
  [Test] public void RenunciaIgnoresArmorAndShield(){var m=New();var a=A(m);var b=Enemy(m);b.cell=new Cell(3,2);b.armor=2;b.hp=20;a.twinBondUsed=true;Strike(m,a,b,Fixed(a,"renuncia",3),Face.Escudo);Assert.AreEqual(17,b.hp);}
  [Test] public void PactoAlwaysDealsTwoIgnoringDice(){var m=New();var a=A(m);var b=Enemy(m);b.cell=new Cell(3,2);b.hp=100;var values=new HashSet<int>();foreach(int _ in Enumerable.Range(0,20)){int hp=b.hp;Strike(m,a,b,Content.Skill(a,"pacto"));values.Add(hp-b.hp);}CollectionAssert.AreEquivalent(new[]{2},values);}
  [TestCase("pacto","renuncia")][TestCase("renuncia","pacto")]
  public void TwinBondAddsOneToSecondDistinctSwordOnlyOnce(string first,string second){var m=New();var a=A(m);var b=Enemy(m);b.cell=new Cell(3,2);b.hp=50;Strike(m,a,b,Fixed(a,first));Assert.AreEqual(48,b.hp);Strike(m,a,b,Fixed(a,second));Assert.AreEqual(45,b.hp);Strike(m,a,b,Fixed(a,first));Assert.AreEqual(43,b.hp);Assert.IsTrue(a.twinBondUsed);Call(m,"ResetTwinBond",a);Assert.IsFalse(a.twinBondUsed);Assert.IsEmpty(a.pactTargets);Assert.IsEmpty(a.renounceTargets);}
  [Test] public void TwinBondCannotTriggerOutsideOwnerTurn(){var m=New();var a=A(m);var b=Enemy(m);b.cell=new Cell(3,2);m.S.active=m.S.timeline.IndexOf(b.id);Strike(m,a,b,Fixed(a,"pacto"));Strike(m,a,b,Fixed(a,"renuncia"));Assert.IsFalse(a.twinBondUsed);}
  [Test] public void TwinBondDoesNotMixEnemies(){var m=New();var a=A(m);var b=Enemy(m);var c=(Fighter)Call(m,"Spawn","perry",b.team,new Cell(2,3),0);b.cell=new Cell(3,2);Strike(m,a,b,Fixed(a,"pacto",1));Strike(m,a,c,Fixed(a,"renuncia",1));Assert.IsFalse(a.twinBondUsed);}
  [Test] public void TwinBondAndGuardSurviveSnapshot(){var m=New("tchu-tcha");var a=A(m);a.directionalGuard=true;a.guardDirection=new Cell(1,0);a.guardSkill="guarda-direcional";a.twinBondUsed=true;a.pactTargets.Add(7);var copy=JsonUtility.FromJson<MatchState>(JsonUtility.ToJson(m.S)).F(a.id);Assert.IsTrue(copy.directionalGuard);Assert.AreEqual(a.guardDirection,copy.guardDirection);Assert.IsTrue(copy.twinBondUsed);CollectionAssert.AreEqual(a.pactTargets,copy.pactTargets);}
  [Test] public void TreatRequiresAnotherLivingAlly(){var m=New();var a=A(m);var sk=Content.Skill(a,"doce-e-salgado");Assert.IsFalse(m.CanTarget(a,sk,a.cell,out _));var ally=m.S.fighters.First(x=>x.team==a.team&&x!=a);ally.cell=new Cell(3,2);ally.hp=0;Assert.IsFalse(m.CanTarget(a,sk,ally.cell,out _));}
  [Test] public void TreatCanEndWithOneOtherAllyAndNeverOverheal(){var m=New();var a=A(m);var allies=m.S.fighters.Where(x=>x.team==a.team&&x!=a).ToList();allies[0].cell=new Cell(3,2);allies[1].cell=new Cell(2,3);a.hp=Content.MaxHp(a)-1;allies[0].hp=1;allies[1].hp=1;Assert.IsTrue(Use(m,a,"doce-e-salgado",allies[0].cell,a.cell,out _,out var why),why);Assert.AreEqual(Content.MaxHp(a),a.hp);Assert.AreEqual(3,allies[0].hp);Assert.AreEqual(1,allies[1].hp);Assert.IsFalse(Use(m,a,"doce-e-salgado",allies[0].cell,a.cell,out _,out _));}
  [Test] public void TreatCanSelectTwoOtherAlliesExactlyOnceEach(){var m=New();var a=A(m);var allies=m.S.fighters.Where(x=>x.team==a.team&&x!=a).ToList();allies[0].cell=new Cell(3,2);allies[1].cell=new Cell(2,3);a.hp=1;foreach(var x in allies)x.hp=1;Assert.IsTrue(Use(m,a,"doce-e-salgado",allies[0].cell,allies[1].cell,out _,out var why),why);Assert.AreEqual(3,a.hp);Assert.IsTrue(allies.All(x=>x.hp==3));}
  [Test] public void TreatRejectsSameAllyTwiceAndEnemy(){var m=New();var a=A(m);var ally=m.S.fighters.First(x=>x.team==a.team&&x!=a);ally.cell=new Cell(3,2);var enemy=Enemy(m);enemy.cell=new Cell(2,3);var sk=Content.Skill(a,"doce-e-salgado");Assert.IsFalse(m.CanTarget(a,sk,ally.cell,ally.cell,out _));Assert.IsFalse(m.CanTarget(a,sk,ally.cell,enemy.cell,out _));}
  [Test] public void TwilightStepHasRealCooldownAndDoesNotRollLock(){var m=New();var a=A(m);var b=Enemy(m);b.cell=new Cell(3,2);m.Forced.Enqueue(Face.Trava);Assert.IsTrue(Use(m,a,"passo-do-crepusculo",new Cell(2,4),default,out _,out var why),why);Assert.AreEqual(new Cell(2,4),a.cell);Assert.AreEqual(1,m.Forced.Count);Assert.AreEqual(1,a.cooldowns.Single(x=>x.skill=="passo-do-crepusculo").uses);}
  [Test] public void RuptureHitsLargeEnemyOnceAndNeverAllies(){var m=New("somnax","colosso");var a=A(m);var b=Enemy(m);b.cell=new Cell(4,2);var ally=m.S.fighters.First(x=>x.team==a.team&&x!=a);ally.cell=new Cell(3,2);int hp=b.hp,friend=ally.hp;m.Forced.Clear();m.Forced.Enqueue(Face.Trava);m.Forced.Enqueue(Face.Trava);Assert.IsTrue(Use(m,a,"ruptura-das-memorias",new Cell(4,2),default,out var e,out var why),why);Assert.AreEqual(hp-5,b.hp);Assert.AreEqual(friend,ally.hp);Assert.AreEqual(1,e.Count(x=>x.kind=="ataque"&&x.target==b.id));}
  [Test] public void GuardActivationBlocksVoluntaryMoveAndAttackAndDirectionChange(){var m=New("tchu-tcha");var a=A(m);Assert.IsTrue(Use(m,a,"guarda-direcional",new Cell(3,2),default,out _,out var why),why);Assert.IsTrue(Match.GuardActive(a));Assert.IsFalse(m.Apply(new Command{kind="mover",fighter=a.id,revision=m.S.revision,cell=new Cell(2,3)},a.team,out _,out _));Assert.IsFalse(Use(m,a,"escudada",new Cell(3,2),default,out _,out _));Assert.IsFalse(Use(m,a,"guarda-direcional",new Cell(2,3),default,out _,out _));Assert.IsTrue(Use(m,a,"guarda-direcional",a.cell,default,out _,out _));Assert.IsFalse(Match.GuardActive(a));Assert.IsTrue(Use(m,a,"guarda-direcional",new Cell(2,3),default,out _,out _));Assert.AreEqual(new Cell(0,1),a.guardDirection);}
  [TestCase(5,2,true)][TestCase(1,2,false)][TestCase(2,5,false)][TestCase(5,4,true)]
  public void GuardOnlyCoversAttacksFromDefendedSide(int sx,int sz,bool covered){var m=New("tchu-tcha");var a=A(m);var ally=m.S.fighters.First(x=>x.team==a.team&&x!=a);ally.cell=new Cell(3,2);var enemy=Enemy(m);enemy.cell=new Cell(sx,sz);a.directionalGuard=true;a.guardDirection=new Cell(1,0);a.guardSkill="guarda-direcional";Assert.AreEqual(covered,Call(m,"DirectionalGuardFor",enemy,ally)!=null);}
  [Test] public void GuardHasRadiusTwoAndNeverStacksOrProtectsOwnerItself(){var m=New("tchu-tcha");var a=A(m);a.directionalGuard=true;a.guardDirection=new Cell(1,0);a.guardSkill="guarda-direcional";var ally=m.S.fighters.First(x=>x.team==a.team&&x!=a);var enemy=Enemy(m);enemy.cell=new Cell(7,2);ally.cell=new Cell(4,2);Assert.AreSame(a,Call(m,"DirectionalGuardFor",enemy,ally));ally.cell=new Cell(5,2);Assert.IsNull(Call(m,"DirectionalGuardFor",enemy,ally));Assert.IsNull(Call(m,"DirectionalGuardFor",enemy,a));}
  [Test] public void PrimalAcquisitionBroadcastsOnceWithoutCoordinatesEvenWhenHidden(){var m=New("colosso");var a=A(m);var b=Enemy(m);var log=new List<GameEvent>();a.hidden=true;Call(m,"Devour",a,b,log);Call(m,"Devour",a,b,log);Assert.AreEqual(1,log.Count(x=>x.kind=="voz-global"));foreach(int p in new[]{1,2}){var filtered=Match.EventsFor(log,m.S,p,new[]{a.id});var e=filtered.Single(x=>x.kind=="voz-global");Assert.AreEqual("primal_cacador",e.info);Assert.AreEqual(Cell.Unknown,e.cell);Assert.AreEqual(Cell.Unknown,e.aim);Assert.IsNull(e.path);Assert.AreEqual(0,e.target);}}
  [Test] public void DamianGreetingUsesStablePeleIdAndOnlyOneAcceptedCommand(){var m=New("damian","pele-negra");var a=A(m);Assert.IsTrue(m.Apply(new Command{kind="mover",fighter=a.id,revision=m.S.revision,cell=new Cell(2,3)},a.team,out var e,out var why),why);Assert.AreEqual(1,e.Count(x=>x.kind=="voz-personagem"&&x.info=="damian_pele_d_ark"));Assert.IsTrue(m.Apply(new Command{kind="mover",fighter=a.id,revision=m.S.revision,cell=new Cell(2,2)},a.team,out e,out _));Assert.IsFalse(e.Any(x=>x.kind=="voz-personagem"));}
  [Test] public void NewResourcesHaveAllFourteenDistinctShortMonoClips(){var seen=new HashSet<AudioClip>();foreach(var id in ArenaVoiceCatalog.Ids){var c=ArenaPresentation.RecordedLine(id);Assert.NotNull(c,id);Assert.IsTrue(seen.Add(c));Assert.AreEqual(1,c.channels,id);Assert.AreEqual(44100,c.frequency,id);Assert.That(c.length,Is.InRange(.1f,30f),id);}}
  [Test] public void JackWaitsForActualVoiceDurationAndStillHasNativeWindup(){Assert.AreEqual(6.2f,ArenaVoiceCatalog.JackWindupSeconds(1,6.2f));Assert.That(ArenaVoiceCatalog.JackWindupSeconds(2,0),Is.EqualTo(14f/9f).Within(.001f));Assert.AreEqual(0,ArenaVoiceCatalog.JackWindupSeconds(0,-1));}
  [Test] public void GuardRigDoesNotReplaceNormalOrBerserkAssets(){var f=A(New("tchu-tcha"));Assert.AreEqual("TchuTcha",ArenaPresentation.SpriteFolder(f));f.directionalGuard=true;Assert.AreEqual("TchuTchaGuarda",ArenaPresentation.SpriteFolder(f));f.form="berserk";Assert.AreEqual("TchuTchaBerserk",ArenaPresentation.SpriteFolder(f));}
  [Test] public void GuardDoesNotCoverWhilePrisonedOrBanished(){var m=New("tchu-tcha");var a=A(m);a.directionalGuard=true;Assert.IsTrue(Match.GuardActive(a));a.prisoned=1;Assert.IsFalse(Match.GuardActive(a));a.prisoned=0;a.banished=true;Assert.IsFalse(Match.GuardActive(a));}
  [Test] public void BotCanDeactivateGuardInsteadOfRepeatingInvalidMovement(){var m=New("tchu-tcha");var a=A(m);a.directionalGuard=true;a.guardSkill="guarda-direcional";var cmd=Bot.Decide(m);Assert.AreEqual("skill",cmd.kind);Assert.AreEqual("guarda-direcional",cmd.skill);Assert.AreEqual(a.cell,cmd.cell);}
  [Test] public void DeadDamianDoesNotGreet(){var m=New("damian","pele-negra");var a=A(m);a.hp=0;Call(m,"DamianGreeting",a);Assert.IsFalse(a.usedMatch.Contains("voz:damian-capitao"));}
  [Test] public void GuardCanReduceFriendlyFireFromDefendedSide(){var m=New("tchu-tcha");var a=A(m);a.directionalGuard=true;a.guardDirection=new Cell(1,0);var friends=m.S.fighters.Where(x=>x!=a&&x.team==a.team).ToList();friends[0].cell=new Cell(3,2);friends[1].cell=new Cell(5,2);Assert.AreSame(a,Call(m,"DirectionalGuardFor",friends[1],friends[0]));}
  [Test] public void SwordUseCapsAreEnforcedByAuthoritativeCommands(){var m=New();var a=A(m);var b=Enemy(m);b.cell=new Cell(3,2);b.hp=100;for(int i=0;i<3;i++){m.Forced.Clear();m.Forced.Enqueue(Face.Trava);m.Forced.Enqueue(Face.Trava);Assert.AreEqual(i<2,Use(m,a,"pacto",b.cell,default,out _,out _));}m.Forced.Clear();m.Forced.Enqueue(Face.Trava);m.Forced.Enqueue(Face.Trava);Assert.IsTrue(Use(m,a,"renuncia",b.cell,default,out _,out _));Assert.IsFalse(Use(m,a,"renuncia",b.cell,default,out _,out _));}
  [Test] public void BotValuesRenunciaAgainstArmorAndUsesExpectedVariableDamage(){var m=New();var a=A(m);var b=Enemy(m);b.armor=10;b.hp=Content.MaxHp(b);var method=typeof(Bot).GetMethod("Hit",BindingFlags.Static|BindingFlags.NonPublic);double score=(double)method.Invoke(null,new object[]{m.S,a,Content.Skill(a,"renuncia"),b,true});Assert.That(score,Is.EqualTo(2.0).Within(.001),"Renúncia: 2 fixos, ignora armadura e Escudo");double blocked=(double)method.Invoke(null,new object[]{m.S,a,Content.Skill(a,"pacto"),b,true});Assert.AreEqual(0,blocked);}
  [Test] public void NewWireVersionRejectsOldClients(){Assert.AreEqual(16,new WireMessage().protocol);}
 }
}
